draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // anna
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // society
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.stroke();

  // love
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50 * Math.cos(t), H/2 + 50 * Math.sin(t));
  ctx.stroke();

  // consequence
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50 * Math.cos(t + Math.PI), H/2 + 50 * Math.sin(t + Math.PI));
  ctx.stroke();

  ctx.restore();
}
